let ripples = []
const rippleWidth = 3

let cols;
let rows;
let current; // = new float[cols][rows];
let previous; // = new float[cols][rows];

// TODO: see if there's a way to make the ripple trigger the bells itself

let dampening = 0.996;

let bells = []
const bellNotes = {
  A3: 160,
  C3: 120,
  D3: 80,
  E3: 40,
  G3: 20,
  A4: 10
}

function setup() {
  // setup canvas
  let canvas = createCanvas(windowWidth, windowHeight);
  background('#74ccf4')
  canvas.parent("wrapper");

  // ripple shader vars
  pixelDensity(1);

  loadPixels()
  // this is processing the current pixels and processing them as a function of its neighbours (i,j are the x,y)
  for (let i = 1; i < cols - 1; i++) {
    for (let j = 1; j < rows - 1; j++) {
      
      // the pixels array in p5.js has 4 entries
      // for each pixel, so we have to multiply the index by 4 and then
      // set the entries for each color component separately.
      let index = (i + j * cols) * 4;
      pixels[index + 0] = 0 // red
      pixels[index + 1] = 255; // green
      pixels[index + 2] = 255; // blue
      //pixels[index + 3] = 0; // alpha
    }
  }
  updatePixels();


  //noSmooth();
  cols = width;
  rows = height;
  // The following line initializes a 2D cols-by-rows array with zeroes
  // in every array cell, and is equivalent to this Processing line:
  // current = new float[cols][rows];
  current = new Array(cols).fill(0).map(n => new Array(rows).fill(0));
  previous = new Array(cols).fill(0).map(n => new Array(rows).fill(0));

  // reset button
  button = createButton('Reset');
  button.parent("wrapper");
  button.position((windowWidth/2)-10, windowHeight/12, 'absolute');
  button.mousePressed(() => {
    location.reload()
  });

  // create bells
  for(const note in bellNotes) {
    s = bellNotes[note] // size
    bells.push(new makeBells(random(75, windowWidth-50), random(75, windowHeight-50), s))
  }
}

// function mouseDragged() {
//   previous[mouseX][mouseY] = 2500;
// }


function draw() {
  background('#74ccf4')

  loadPixels()
  // this is processing the current pixels and processing them as a function of its neighbours (i,j are the x,y)
  for (let i = 1; i < cols - 1; i++) {
    for (let j = 1; j < rows - 1; j++) {
      current[i][j] =
        (previous[i - 1][j] +
          previous[i + 1][j] +
          previous[i][j - 1] +
          previous[i][j + 1]) /2 - 
          current[i][j];
      current[i][j] = current[i][j] * dampening;
      
      // the pixels array in p5.js has 4 entries
      // for each pixel, so we have to multiply the index by 4 and then
      // set the entries for each color component separately.
      let index = (i + j * cols) * 4;
      pixels[index + 0] = 0 // red
      pixels[index + 1] = current[i][j] + 200; // green
      pixels[index + 2] = current[i][j] + 255; // blue
      //pixels[index + 3] = 0; // alpha
    }
  }
  updatePixels();

  // water ripple effect
  let temp = previous;
  previous = current;
  current = temp;

  // update and display bells each time draw loops
  for (let i = 0; i < bells.length; i++) {
    //bells[i].update();
    bells[i].ellipse();
  }

  // update and display ripples each time draw loops
  for (let i = 0; i < ripples.length; i++) {
    ripples[i].update();
    ripples[i].ellipse();

    for (let j = 0; j < bells.length; j++) {
      // check for collision and play bell sound
        overlap = checkOverlap(ripples[i], bells[j])
        if (overlap && bells[j].triggered === false) {
          note = Object.keys(bellNotes)[j];
          const sound = new Audio(`audio/${note}.mp3`)
          sound.play();

          // Mark the bell as triggered to avoid repeated triggering
          bells[j].triggered = true;
          // triggered bells glow brighted
          bells[j].g += 50
          bells[j].b += 50
        }

        //console.log(`Bell ${j + 1} trigger state: ${bells[j].triggered}`);
    }

    // delete ripple if reach lifespan
    if (ripples[i]. lifespan <= 0) {
      ripples.splice(i, 1)
    }
  }
}

// add a ripple whenever the mouse is clicked (will need to add exception for clicking on a bell)
function mouseClicked(){

  // check if user is clicking a bell object
  // const mousePos = {x: mouseX, y: mouseY}

  // if(bellPositions.indexOf(mousePos)) {
  //   console.log(bellPositions.indexOf(mousePos))
  //   selectBell()
  // }
  // else {
  //   // push new ripple into array
  //   ripples.push(new makeRipple(mouseX, mouseY, random(1, 5))) // third parameter is a random size
  // }

  previous[mouseX][mouseY] = 2500;

  ripples.push(new makeRipple(mouseX, mouseY, 1, rippleWidth)) // third parameter is a random size

}

function selectBell() {
  return
}

function makeBells(x, y, s) {
  // set properties
  this.x = x // x pos
  this.y = y // y pos
  this.s = s; // size

  // color values
  this.r = random(205)
  this.g = random(205)
  this.b = random(205)

  // property to track if the bell has been triggered
  this.triggered = false;

  this.ellipse = function() {
    // define visual properties
    fill(this.r, this.g, this.b, this.a)
    noStroke()

    // draw ellipse
    ellipse(this.x, this.y, this.s)
  }

  // reset bell trigger state after some time (could do a proper timer later, this is a hack job)
  // this.update = function() {
  //   // if (this.triggered = true && frameCount % 120 == 0) {
  //   //   this.triggered = false
  //   // }
  // }
}

// class for making ripples
function makeRipple(x, y, s, w) {
  // set properties
  this.x = x // x pos
  this.y = y // y pos
  this.s = s // size
  this.w = w // line width

  // color values
  this.r = 0
  this.g = 170
  this.b = 255
  this.a = 0 // 0 alpha with new ripple effect

  // lifespan
  this.lifespan = 750

  // function to create ripple
  this.ellipse = function() {
    // define visual properties
    stroke(this.r, this.g, this.b, this.a)
    strokeWeight(this.w)
    noFill();

    // draw ellipse
    ellipse(this.x, this.y, this.s)
  }

  // grow the ellipse and fade
  this.update = function() {
    this.s = this.s + 1.41;
    //this.a = this.a - 0.7;
    this.lifespan--;
    stroke(this.r, this.g, this.b, this.a)
  }
}

// Function to check if two circles overlap
function checkOverlap(circle1, circle2) {
  const dx = circle1.x - circle2.x;
  const dy = circle1.y - circle2.y;
  const distance = Math.sqrt(dx * dx + dy * dy);
  const bellRadiiPlusRipple = circle1.s/2 + circle2.s/2;

  return distance < bellRadiiPlusRipple;
}
